export const meta = {
  name: 'duplicate-code-audit',
  description: 'Find, merge and adversarially verify duplicate or refactorable code across the Frame Job product sources',
  phases: [
    { title: 'Find', detail: 'one reader per area plus a cross-cutting reader' },
    { title: 'Merge', detail: 'dedupe candidates across areas' },
    { title: 'Verify', detail: 'behaviour and worth lenses per candidate' },
    { title: 'Gaps', detail: 'completeness critic and gap readers' },
  ],
}

const AREAS = args.areas

const RULES = `
Repository context (Frame Job, a macOS video editor: Swift/AppKit app in app/Sources over a Rust core in core/src, plus graphic/ and mcp-proxy/ crates).
You are READ-ONLY: never edit, write, create, stage or delete any file in the repository. Use Read/Grep/Bash (cat, sed -n, grep, wc) only.
Never open, list or grep anything under .secrets/.
Rules that bound what a refactor may do (read app/CLAUDE.md and core/CLAUDE.md for detail if a candidate touches them):
- Frozen files take wiring only: app/Sources/EditorViewController.swift, TimelineView.swift, PreviewCanvasView.swift, AgentServer.swift.
- Files are capped at ~600 lines (new files 400); a file at the cap must give something up (a pure move) before taking anything on. core/src/edit.rs and app/Sources/ReelOps.swift are exempt.
- DELIBERATE duplication that is NOT a finding: the op mirrors (core/src/op_table.rs, ReelOps.swift typed builders, AgentCatalog*.swift entries, spec section 6) and the FFI's three files in lockstep (Rust #[no_mangle] export, core/include/framejob_core.h, app/Sources/ReelCore.swift) - flag only if one copy could be GENERATED from another; core/src/schema_v*.rs frozen format snapshots; agent/src (byte-identical with another repo); anything in tools/proof (out of scope); spec section 11 decisions.
- Small repetitions of idiomatic boilerplate (a guard let, a two-line NSLayoutConstraint pair) are not findings. A finding should remove a meaningful amount of repeated logic or prevent copies from drifting.
What counts: (1) exact or near-exact copy-paste blocks; (2) the same logic in different shapes (semantic clones) - e.g. several handlers each reading arguments, building refusals, running a progress sheet, computing time conversions, building controls, walking tracks/clips the same way; (3) Swift re-implementing what the Rust core (or graphic crate) already computes, or vice versa; (4) MOST VALUABLE: copies that have already DRIFTED - one copy got a fix, a guard, a clamp or an edge case the other lacks. Record drift precisely with both line ranges.
For each candidate propose a CONCRETE refactor: the shared helper/type/protocol name, the file it would live in (respecting caps and frozen files), its signature, and which sites call it. Estimate lines removed honestly.
Cite exact file paths and line ranges you have actually read.`

const FINDING = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    kind: { type: 'string', enum: ['exact', 'near', 'semantic', 'cross-language', 'drifted'] },
    sites: { type: 'array', items: { type: 'object', properties: {
      file: { type: 'string' }, start_line: { type: 'integer' }, end_line: { type: 'integer' }, note: { type: 'string' } },
      required: ['file', 'start_line', 'end_line', 'note'] } },
    what: { type: 'string', description: 'what is duplicated and why it is the same logic' },
    drift: { type: 'string', description: 'concrete behavioural differences between copies; empty string if none' },
    refactor: { type: 'string', description: 'concrete proposal: helper name, home file, signature, callers' },
    est_lines_removed: { type: 'integer' },
    touches_frozen_or_capped: { type: 'string', description: 'which frozen or near-cap files are involved and how the refactor respects the rules; empty if none' },
    risk: { type: 'string', enum: ['low', 'medium', 'high'] },
  },
  required: ['title', 'kind', 'sites', 'what', 'drift', 'refactor', 'est_lines_removed', 'touches_frozen_or_capped', 'risk'],
}
const FINDINGS = { type: 'object', properties: { findings: { type: 'array', items: FINDING }, coverage_notes: { type: 'string', description: 'files you did not get to read, if any' } }, required: ['findings', 'coverage_notes'] }

function finderPrompt(a) {
  return `${RULES}

Your area: ${a.key} - ${a.desc} (${a.files.length} files, ${a.lines} lines).
Files:
${a.files.join('\n')}

A token-based clone detector (jscpd, weak mode, >=40 tokens, >=5 lines) reported these pairs touching your area (lines, siteA == siteB). Examine every one and decide whether it is a real finding; some partner sites lie outside your area - read them too:
${a.clone_hits.length ? a.clone_hits.join('\n') : '(none)'}

Then READ your area's files thoroughly (all of them; skim large tables) looking for semantic duplication the detector cannot see - repeated patterns across sibling files (the +Feature extension files, sheet controllers, handlers, panes, ops) are the prime targets. You may grep the rest of the repository to find copies of a pattern outside your area. Return every candidate worth a refactor, ranked by value. Aim for thoroughness over volume; do not pad.`
}

const CROSS = `${RULES}

Your area: CROSS-CUTTING duplication that per-area readers will miss, across all of app/Sources, core/src, graphic/src and mcp-proxy/src. Hunt specifically for:
- Utility logic re-implemented in several places: time/frame/timecode conversion and formatting, rational time arithmetic, clamping, JSON dictionary reading and number coercion, file/URL/path building under the package or Application Support, unique-name generation, alert/NSError construction, colour conversions, dB/gain conversions, debouncing/throttling, background-queue + main-thread hop patterns, AVAsset loading, CMTime helpers, temporary-file handling.
- Swift code recomputing something the Rust core already answers (or could answer through an existing rc_* query), and Rust logic duplicated between core/src and graphic/src (jscpd found core/src/model_graphic.rs vs graphic/src/props.rs).
- Parallel enums/tables kept in sync by hand across Swift files (not the deliberate op/FFI mirrors).
Use grep heavily (e.g. grep -rn "func .*timecode\\|CMTimeMake\\|/ 1000\\b\\|clamp" etc.) and read the hits. Return every candidate worth a refactor, ranked by value.`

phase('Find')
const finderJobs = AREAS.map(a => () => agent(finderPrompt(a), { label: `find:${a.key}`, phase: 'Find', schema: FINDINGS }))
finderJobs.push(() => agent(CROSS, { label: 'find:cross-cutting', phase: 'Find', schema: FINDINGS }))
const found = (await parallel(finderJobs)).filter(Boolean)
const raw = found.flatMap(r => r.findings)
const coverage = found.map(r => r.coverage_notes).filter(s => s && s.trim()).join('\n')
log(`${raw.length} raw candidates from ${found.length} readers`)

phase('Merge')
const MERGED = { type: 'object', properties: { candidates: { type: 'array', items: { ...FINDING, properties: { ...FINDING.properties, id: { type: 'string', description: 'short kebab-case id' }, merged_from: { type: 'array', items: { type: 'string' } } }, required: [...FINDING.required, 'id'] } } }, required: ['candidates'] }
const merged = await agent(`${RULES}

Below are ${raw.length} duplicate-code candidates from independent readers, as JSON. Several readers may have reported the same duplication (same sites, or overlapping sites, or one candidate subsuming another). Merge duplicates into one candidate each (union the sites, keep the most concrete refactor and the most precise drift note, list the merged titles in merged_from). Do NOT drop any distinct candidate and do not judge worth - that is the next stage. Where two candidates would be served by one shared abstraction, merge them. Give each a short kebab-case id. You may read files to resolve overlaps.

${JSON.stringify(raw)}`, { label: 'merge', phase: 'Merge', schema: MERGED })
const candidates = merged ? merged.candidates : []
log(`${candidates.length} candidates after merge`)

const VERDICT = { type: 'object', properties: {
  verdict: { type: 'string', enum: ['confirm', 'reject'] },
  drift_is_real_bug: { type: 'boolean', description: 'true only if a copy demonstrably lacks behaviour the other has and that difference is wrong (not intentional)' },
  reasons: { type: 'string' },
  corrections: { type: 'string', description: 'wrong line numbers, missed sites, behaviour differences the refactor must preserve, or a better refactor; empty if none' },
  est_lines_removed: { type: 'integer' } },
  required: ['verdict', 'drift_is_real_bug', 'reasons', 'corrections', 'est_lines_removed'] }

const LENSES = {
  behaviour: `Lens: BEHAVIOUR. Try to REFUTE that these sites are the same logic. Read every site in full context. List every behavioural difference (ordering, edge cases, rounding, error text, threading, undo naming, which document/window, clamps). Decide whether a single shared implementation can preserve each site's behaviour exactly (parameters allowed) - if differences are intentional and would need so many parameters that the helper is worse than the copies, reject. Separately judge whether any drift is a real bug. Default to reject if the sites are not genuinely the same logic.`,
  worth: `Lens: WORTH AND RULES. Try to REFUTE that this refactor is worth doing. Check: real lines removed (verify the estimate by reading), whether the abstraction couples code that changes for different reasons, whether it is deliberate duplication listed in the rules, whether it fights the frozen-file or 600-line cap rules (run wc -l on involved files) or the repo's architecture (Rust decides, Swift does; ReelCore.swift is the only rc_* caller; ProjectDocument is the single mutation point). Reject trivial or churn-only refactors (under ~15 lines removed with no drift risk). Default to reject if uncertain.`,
}

phase('Verify')
const verified = await parallel(candidates.map(c => () =>
  parallel(Object.entries(LENSES).map(([k, lens]) => () => agent(`${RULES}

${lens}

Candidate:
${JSON.stringify(c, null, 1)}`, { label: `verify:${k}:${c.id}`, phase: 'Verify', schema: VERDICT })))
    .then(vs => {
      const ok = vs.filter(Boolean)
      const confirms = ok.filter(v => v.verdict === 'confirm').length
      const drift = ok.some(v => v.drift_is_real_bug)
      return { ...c, votes: ok, confirmed: confirms === ok.length && ok.length === 2, drift_bug: drift }
    })))
const kept = verified.filter(Boolean).filter(c => c.confirmed || c.drift_bug)
log(`${kept.length} of ${candidates.length} survived verification (${kept.filter(c => c.drift_bug).length} with a real drift bug)`)

phase('Gaps')
const GAPS = { type: 'object', properties: { gaps: { type: 'array', items: { type: 'object', properties: {
  focus: { type: 'string', description: 'a precise instruction for a gap reader: which files or which pattern to examine' } }, required: ['focus'] } } }, required: ['gaps'] }
const critic = await agent(`${RULES}

You are a completeness critic for a duplicate-code audit of app/Sources, core/src, graphic/src and mcp-proxy/src. The areas read were: ${AREAS.map(a => a.key + ' (' + a.desc + ')').join('; ')}; plus a cross-cutting reader.
Readers' coverage notes (files not read): ${coverage || '(none)'}
Candidates already found (titles): ${candidates.map(c => c.id + ': ' + c.title).join(' | ')}
Name at most 4 specific gaps worth another reader: files unread, sibling-file families with no candidate where duplication is likely (grep and sample to check before naming one), or pattern classes nobody hunted. Return an empty list if coverage is adequate.`, { label: 'critic', phase: 'Gaps', schema: GAPS })
const gapFocus = critic ? critic.gaps.slice(0, 4) : []
log(`critic named ${gapFocus.length} gaps`)
const gapFound = (await parallel(gapFocus.map((g, i) => () => agent(`${RULES}

Gap reader. Focus: ${g.focus}
Already-known candidates (do not re-report): ${candidates.map(c => c.id + ': ' + c.title).join(' | ')}
Return only NEW candidates.`, { label: `gap:${i}`, phase: 'Gaps', schema: FINDINGS })))).filter(Boolean).flatMap(r => r.findings)
const gapVerified = await parallel(gapFound.map((c, i) => () =>
  parallel(Object.entries(LENSES).map(([k, lens]) => () => agent(`${RULES}

${lens}

Candidate:
${JSON.stringify(c, null, 1)}`, { label: `verify-gap:${k}:${i}`, phase: 'Gaps', schema: VERDICT })))
    .then(vs => {
      const ok = vs.filter(Boolean)
      return { ...c, id: 'gap-' + i, votes: ok, confirmed: ok.length === 2 && ok.every(v => v.verdict === 'confirm'), drift_bug: ok.some(v => v.drift_is_real_bug) }
    })))
const gapKept = gapVerified.filter(Boolean).filter(c => c.confirmed || c.drift_bug)

return {
  raw_count: raw.length,
  merged_count: candidates.length,
  kept: [...kept, ...gapKept],
  rejected: [...verified, ...gapVerified].filter(Boolean).filter(c => !(c.confirmed || c.drift_bug)).map(c => ({ id: c.id, title: c.title, reasons: c.votes.map(v => v.verdict + ': ' + v.reasons) })),
  coverage,
}

