}

async function runIssue(L, it) {
  const H = `/Users/kevingalligan/.claude/litecode/framejob/${it.dir}`
  const tag = `#${it.n}`
  const opts = (stage, extra) => ({ label: `${L.lane}:${tag} ${stage}`, phase: L.phase, ...extra })

  const implPrompt = it.route === 'full'
    ? `Handoff dir: ${H}. Read 03-spec-final.md. Implement it. Write 04-impl-notes.md and 04-checks.txt. ${laneNote(L)} If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
    : `Handoff dir: ${H}. Read request.md and 00-triage.md. No spec exists; implement the request directly, touching only files_likely_touched unless you justify otherwise in your notes. Write 04-impl-notes.md and 04-checks.txt. ${laneNote(L)} If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
  const impl = await agent(implPrompt, opts('implement', { agentType: 'lc-implementer', schema: IMPL }))
