      if (pass > 2 && stuck.length) return { n: it.n, status: 'stopped', detail: `stuck findings: ${stuck.join(' | ')}` }
      prev = rev.findings
      const fx = await agent(`Handoff dir: ${H}. Read ${reviewFile} and the git diff (git -C ${L.path} diff HEAD). Fix every blocker and should-fix. Re-run the spec's verification commands that your fixes can affect. Write 06-fix-notes-${pass}.md. ${laneNote(L)}`,
        opts(`fix ${pass}`, { agentType: 'lc-fixer', schema: FIX }))
      if (!fx || fx.status === 'stop') return { n: it.n, status: 'stopped', detail: fx ? (fx.stop_reason || fx.summary) : 'fixer returned nothing' }
