      rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 04-impl-notes.md, 04-checks.txt, every 06-fix-notes-*.md so far, ${reviewFile}, and the git diff (git -C ${L.path} diff HEAD plus untracked files). Write ${next}. ${laneNote(L)}`,
