async function runLane(L) {
  phase(L.phase)
  const out = []
  for (const it of L.issues) {
    const r = await runIssue(L, it)
    out.push(r)
    if (r.status !== 'merged') {
      log(`lane ${L.lane}: #${it.n} ${r.status}; lane halted`)
      for (const rest of L.issues.slice(L.issues.indexOf(it) + 1)) out.push({ n: rest.n, status: 'not-run', detail: `lane halted at #${it.n}` })
      break
    }
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

