3. \`git -C W rebase main\`. On conflicts: resolve them (appended sections such as tools/proof/README.md, CLAUDE.md map entries, spec index rows and Lines cells: keep both sides, fix counts; code: keep both intents), add, \`GIT_EDITOR=true git -C W rebase --continue\`. If you cannot resolve one with confidence: \`git -C W rebase --abort\` and return conflict-unresolved naming the files.
4. \`cd W && make gate\` in the foreground (Bash timeout 600000). If it fails because of the rebase or step 1, fix it, \`git -C W commit --amend --no-edit\`, re-run; at most two fixes. Any other failure: return failed with the gate's last lines.
5. \`git -C M status --porcelain --untracked-files=no\` must print nothing (else return failed, don't touch M). Then \`git -C M merge --ff-only ${L.branch}\`. If refused because main moved, go back to step 3 (at most three loops). Retry once on index.lock.
6. If the commit added a file under app/Sources: \`cd M && make project\`.
7. For each issue in ${nums}: \`gh issue close N --comment "<text>"\` from M: "Fixed in <short sha> (main, not pushed): <what changed for this issue>. Verified: <short list>; make gate PASS." If the notes say an issue is only partly done, comment instead of closing and say what is left.
8. Each "To file" item in the notes: \`gh issue create --label ai-drafted --label low-priority --title ... --body ...\` from M (body names the batch's commit). Return them in filed.
9. Append one line to ${LOG}: "<date> <sha> lane-${L.lane} ${nums} <subject>".
Never push, never force, never touch another worktree. Return the merged short sha.`,
    opts('integrate', { agentType: 'general-purpose', schema: INTEGRATE })))
  if (!integ) return { dir: B.dir, issues: B.issues, status: 'failed', dirty: true, detail: 'integrator returned nothing' }
  if (integ.status !== 'merged') return { dir: B.dir, issues: B.issues, status: integ.status, dirty: true, detail: integ.detail }
  log(`${tag} merged to main as ${integ.sha}`)
  return { dir: B.dir, issues: B.issues, status: 'merged', dirty: false, sha: integ.sha, filed: integ.filed || [], detail: integ.detail }
}

async function runLane(L) {
  phase(L.phase)
  const out = []
  for (let i = 0; i < L.batches.length; i++) {
    const r = await runBatch(L, L.batches[i])
    out.push(r)
    if (r.status !== 'merged' && r.dirty) {
      log(`lane ${L.lane}: ${L.batches[i].dir} ${r.status} with uncommitted work; lane halted`)
      for (const rest of L.batches.slice(i + 1)) out.push({ dir: rest.dir, issues: rest.issues, status: 'not-run', detail: `lane halted at ${L.batches[i].dir}` })
      break
    }
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

