export const meta = { name: "FJ Intro", durationInFrames: 150 };
export const schema = {
  title: { type: "string", default: "Frame Job" },
  tagline: { type: "string", default: "A native video editor for macOS" },
};

const BG = "#0D1512", CREAM = "#FBF8F1", GREEN = "#1F8564", YELLOW = "#F2C14E", CORAL = "#F4653F";

function mark(cx, cy, size, frame, fps) {
  const k = size / 824;
  const spread = interpolate(spring({ frame: frame - 4, fps, damping: 14 }), [0, 1], [260, 0]);
  const fill = spring({ frame: frame - 14, fps, damping: 12 });
  const drop = spring({ frame: frame - 24, fps, damping: 11, stiffness: 140 });
  const corner = (d, dx, dy) =>
    `<path d="${d}" fill="${GREEN}" transform="translate(${dx * spread} ${dy * spread})"/>`;
  const tile = spring({ frame, fps, damping: 16 });
  return `<g transform="translate(${cx} ${cy}) scale(${k * tile}) translate(-512 -512)">
    <rect x="100" y="100" width="824" height="824" rx="214" fill="${CREAM}"/>
    <g clip-path="url(#tile)">
      ${corner("M190 380 V190 H380 V254 H254 V380 Z", -1, -1)}
      ${corner("M834 380 V190 H644 V254 H770 V380 Z", 1, -1)}
      ${corner("M190 644 V834 H380 V770 H254 V644 Z", -1, 1)}
      ${corner("M834 644 V834 H644 V770 H770 V644 Z", 1, 1)}
      <rect x="${512 - 182 * fill}" y="400" width="${364 * fill}" height="224" fill="${YELLOW}"/>
      <g transform="translate(0 ${(1 - drop) * -700})">
        <rect x="488" y="310" width="48" height="424" fill="${CORAL}"/>
        <path d="M461 290 H563 L512 366 Z" fill="${CORAL}"/>
      </g>
    </g>
  </g>`;
}

export function render(frame, props, ctx) {
  const u = ctx.height / 1080;
  const fps = ctx.fps;
  const cx = ctx.width / 2;
  const slide = spring({ frame: frame - 34, fps, damping: 15 });
  const logoY = ctx.height / 2 - interpolate(slide, [0, 1], [0, 110 * u]);
  const titleIn = spring({ frame: frame - 40, fps, damping: 16 });
  const tagIn = interpolate(frame, [58, 76], [0, 1], { easing: Easing.outCubic, clamp: true });
  const out = interpolate(frame, [ctx.durationInFrames - 12, ctx.durationInFrames - 1], [1, 0], { clamp: true });
  const glow = interpolate(frame, [0, 60], [0, 0.55], { clamp: true });
  const titleSize = 150 * u;
  const tw = measureText(props.title, { family: "Montserrat", size: titleSize, weight: 900 }).width;
  const reveal = tw * titleIn;
  return svg(ctx, `
    <defs>
      <radialGradient id="g" cx="50%" cy="45%" r="60%">
        <stop offset="0" stop-color="${GREEN}" stop-opacity="${glow}"/>
        <stop offset="1" stop-color="${BG}" stop-opacity="0"/>
      </radialGradient>
      <clipPath id="tile"><rect x="100" y="100" width="824" height="824" rx="214"/></clipPath>
      <clipPath id="tw"><rect x="${cx - tw / 2}" y="0" width="${reveal}" height="${ctx.height}"/></clipPath>
    </defs>
    <rect width="${ctx.width}" height="${ctx.height}" fill="url(#g)"/>
    <g opacity="${out}">
      ${mark(cx, logoY, 300 * u, frame, fps)}
      <g clip-path="url(#tw)">
        <text x="${cx}" y="${ctx.height / 2 + 240 * u}" text-anchor="middle" font-family="Montserrat"
          font-weight="900" font-size="${titleSize}" fill="${CREAM}">${escapeXml(props.title)}</text>
      </g>
      <text x="${cx}" y="${ctx.height / 2 + 320 * u + (1 - tagIn) * 20 * u}" text-anchor="middle"
        font-family="'Source Sans 3'" font-weight="500" font-size="${50 * u}" letter-spacing="${2 * u}"
        fill="${CREAM}" opacity="${tagIn * 0.8}">${escapeXml(props.tagline)}</text>
    </g>`, { background: BG });
}

export const meta = { name: "FJ Timeline", durationInFrames: 240 };
export const schema = {
  kicker: { type: "string", default: "EDITING" },
  title: { type: "string", default: "Every cut, frame-accurate" },
  chips: { type: "string", default: "Trim,Slip,Roll,Split,Ripple delete,Insert & overwrite,Nests", animate: false },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", TEAL = "#2E9C8A";

function heading(frame, props, ctx, u) {
  const fps = ctx.fps;
  const k = spring({ frame, fps, damping: 16 });
  const t = spring({ frame: frame - 5, fps, damping: 16 });
  let x = 160 * u, chips = "";
  props.chips.split(",").forEach((c, i) => {
    const s = spring({ frame: frame - 18 - i * 4, fps, damping: 14 });
    const w = measureText(c, { family: "Source Sans 3", size: 30 * u, weight: 600 }).width + 40 * u;
    chips += `<g opacity="${Math.min(1, s)}" transform="translate(0 ${(1 - s) * 30 * u})">
      <rect x="${x}" y="${300 * u}" width="${w}" height="${54 * u}" rx="${27 * u}" fill="none" stroke="${GREEN}" stroke-width="${2 * u}"/>
      <text x="${x + w / 2}" y="${337 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600"
        font-size="${30 * u}" fill="${CREAM}">${escapeXml(c)}</text></g>`;
    x += w + 16 * u;
  });
  return `<g opacity="${k}">
    <text x="${160 * u}" y="${150 * u}" font-family="'IBM Plex Mono'" font-weight="500" font-size="${30 * u}"
      letter-spacing="${6 * u}" fill="${CORAL}">${escapeXml(props.kicker)}</text></g>
    <g opacity="${t}" transform="translate(${(1 - t) * -60 * u} 0)">
    <text x="${160 * u}" y="${250 * u}" font-family="Montserrat" font-weight="900" font-size="${92 * u}"
      fill="${CREAM}">${escapeXml(props.title)}</text></g>${chips}`;
}

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const L = 160 * u, R = ctx.width - 160 * u, T = 430 * u, B = 980 * u;
  const pin = spring({ frame: frame - 8, fps, damping: 18 });
  const sec = (R - L - 120 * u) / 20;
  const X = (s) => L + 120 * u + s * sec;
  // ripple: the cut at 9..12 s is removed at 130, later clips slide 3 s left by 165
  const gone = interpolate(frame, [125, 140], [1, 0], { clamp: true });
  const shift = interpolate(frame, [142, 168], [0, 3], { easing: Easing.inOutCubic, clamp: true });
  const rows = [
    { y: T + 70 * u, h: 80 * u, name: "V2", clips: [[2, 7, YELLOW, "Title"], [13, 18, YELLOW, "Lower third"]] },
    { y: T + 170 * u, h: 120 * u, name: "V1", clips: [[0, 5, GREEN, "Interview"], [5, 9, TEAL, "B-roll"], [9, 12, "#3B6B5A", "Cut me"], [12, 20, GREEN, "Interview"]] },
    { y: T + 310 * u, h: 90 * u, name: "A1", clips: [[0, 20, "#7A3B2C", "Music"]] },
  ];
  let body = "";
  rows.forEach((r, ri) => {
    body += `<text x="${L + 40 * u}" y="${r.y + r.h / 2 + 10 * u}" font-family="'IBM Plex Mono'" font-size="${26 * u}" fill="#7F938A">${r.name}</text>`;
    r.clips.forEach((c, ci) => {
      let [a, b, col, label] = c;
      const s = spring({ frame: frame - 20 - ri * 6 - ci * 5, fps, damping: 15 });
      let op = Math.min(1, s);
      if (label === "Cut me") op *= gone;
      if (a >= 12 && r.name !== "A1") { a -= shift; b -= shift; }
      if (r.name === "A1") b -= shift;
      const x = X(a) + 2 * u, w = (b - a) * sec - 4 * u;
      const dy = (1 - s) * 40 * u;
      let wave = "";
      if (r.name === "A1") {
        for (let i = 0; i < w / (6 * u); i++) {
          const amp = (0.3 + 0.7 * Math.abs(noise2D("w", i / 9, 0))) * r.h * 0.38;
          wave += `<rect x="${x + i * 6 * u}" y="${r.y + r.h / 2 - amp}" width="${3 * u}" height="${amp * 2}" fill="${CORAL}" opacity="0.8"/>`;
        }
      }
      body += `<g opacity="${op}" transform="translate(0 ${dy})">
        <rect x="${x}" y="${r.y}" width="${w}" height="${r.h}" rx="${3 * u}" fill="${col}"/>
        ${wave}
        <text x="${x + 14 * u}" y="${r.y + 34 * u}" font-family="'Source Sans 3'" font-weight="700" font-size="${24 * u}"
          fill="${col === YELLOW ? BG : CREAM}">${escapeXml(label)}</text></g>`;
    });
  });
  // ruler
  let ruler = "";
  for (let s = 0; s <= 20; s++) {
    ruler += `<line x1="${X(s)}" y1="${T + 22 * u}" x2="${X(s)}" y2="${T + (s % 5 ? 36 : 46) * u}" stroke="#5A6E64" stroke-width="${2 * u}"/>`;
  }
  // playhead: sweeps to the cut, pauses, blade flash, then continues
  const ph = interpolate(frame, [30, 110, 175, 239], [1, 9, 9, 17.5], { easing: Easing.inOutSine, clamp: true });
  const flash = interpolate(frame, [110, 118, 130], [0, 1, 0], { clamp: true });
  const px = X(ph);
  return svg(ctx, `
    ${heading(frame, props, ctx, u)}
    <g opacity="${pin}" transform="translate(0 ${(1 - pin) * 80 * u})">
      <rect x="${L}" y="${T}" width="${R - L}" height="${B - T}" rx="${14 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
      ${ruler}${body}
      <rect x="${X(9) - 3 * u}" y="${T + 60 * u}" width="${6 * u}" height="${380 * u}" fill="${YELLOW}" opacity="${flash}"/>
      <rect x="${X(12) - 3 * u}" y="${T + 60 * u}" width="${6 * u}" height="${380 * u}" fill="${YELLOW}" opacity="${flash}"/>
      <line x1="${px}" y1="${T + 14 * u}" x2="${px}" y2="${B - 20 * u}" stroke="${CORAL}" stroke-width="${4 * u}"/>
      <path d="M ${px - 14 * u} ${T + 8 * u} H ${px + 14 * u} L ${px} ${T + 30 * u} Z" fill="${CORAL}"/>
    </g>`, { background: BG });
}

export const meta = { name: "FJ Code to motion", durationInFrames: 330 };
export const schema = {
  kicker: { type: "string", default: "MOTION GRAPHICS" },
  title: { type: "string", default: "Write it in JavaScript. Watch it move." },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", MUTED = "#7F938A";

const CODE = [
  "export const schema = {",
  "  title:  { type: \"string\", default: \"Launch day\" },",
  "  accent: { type: \"color\",  default: \"#F4653F\" },",
  "  size:   { type: \"number\", default: 120 },",
  "};",
  "",
  "export function render(frame, props, ctx) {",
  "  const s = spring({ frame, fps: ctx.fps });",
  "  const y = interpolate(s, [0, 1], [80, 0]);",
  "  return svg(ctx, `<text y=\"${y}\" ...>`);",
  "}",
];

function colorize(line) {
  const parts = line.split(/("[^"]*"|`[^`]*`|\b(?:export|const|function|return)\b|\b\d+\b)/);
  return parts.map((p) => {
    if (!p) return "";
    let fill = CREAM;
    if (/^["`]/.test(p)) fill = YELLOW;
    else if (/^(export|const|function|return)$/.test(p)) fill = CORAL;
    else if (/^\d+$/.test(p)) fill = "#7FD1B9";
    else if (/^(spring|interpolate|svg)$/.test(p.trim())) fill = "#7FD1B9";
    return `<tspan fill="${fill}">${escapeXml(p)}</tspan>`;
  }).join("");
}

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const head = spring({ frame, fps, damping: 16 });
  const sub = spring({ frame: frame - 6, fps, damping: 16 });
  const panelIn = spring({ frame: frame - 8, fps, damping: 18 });
  // typing
  const total = CODE.reduce((n, l) => n + l.length + 1, 0);
  const typed = Math.floor(interpolate(frame, [16, 150], [0, total], { clamp: true }));
  let left = typed, code = "", cursor = null;
  const cx0 = 160 * u, cy0 = 360 * u, lh = 46 * u, fs = 27 * u;
  const cw = measureText("M", { family: "IBM Plex Mono", size: fs }).width;
  CODE.forEach((l, i) => {
    const n = Math.max(0, Math.min(l.length, left));
    left -= l.length + 1;
    const y = cy0 + i * lh;
    code += `<text x="${cx0 - 50 * u}" y="${y}" font-family="'IBM Plex Mono'" font-size="${fs * 0.85}" fill="#3F5249">${i + 1}</text>`;
    if (n > 0) code += `<text x="${cx0}" y="${y}" xml:space="preserve" font-family="'IBM Plex Mono'" font-size="${fs}">${colorize(l.slice(0, n))}</text>`;
    if (cursor === null && (left < 0 || i === CODE.length - 1)) cursor = { x: cx0 + n * cw, y };
  });
  const blink = Math.floor(frame / 15) % 2 === 0 || frame < 150;
  if (cursor && blink) code += `<rect x="${cursor.x}" y="${cursor.y - fs * 0.8}" width="${3 * u}" height="${fs}" fill="${CREAM}"/>`;

  // preview
  const PX = 1060 * u, PY = 300 * u, PW = 740 * u, PH = 416 * u;
  const live = frame >= 150;
  const loop = live ? (frame - 150) % 90 : 0;
  const s = live ? spring({ frame: loop, fps, damping: 9 }) : 0;
  const yOff = interpolate(s, [0, 1], [80, 0]) * u * 0.6;
  // inspector edits after 200: accent and size change
  const accent = interpolateColors(frame, [215, 240, 265, 290], [CORAL, CORAL, YELLOW, "#2E9C8A"]);
  const size = interpolate(frame, [215, 250, 300], [120, 120, 150], { easing: Easing.inOutCubic, clamp: true });
  const titleText = frame < 205 ? "Launch day" : "Launch day!".slice(0, Math.min(11, 10 + Math.floor((frame - 205) / 6)));
  const tsz = size * u * 0.55;
  const preview = `<g opacity="${panelIn}">
    <rect x="${PX}" y="${PY}" width="${PW}" height="${PH}" rx="${12 * u}" fill="#0A0F0D" stroke="${LINE}" stroke-width="${2 * u}"/>
    <text x="${PX + 20 * u}" y="${PY - 16 * u}" font-family="'IBM Plex Mono'" font-size="${22 * u}" fill="${MUTED}">PREVIEW</text>
    ${live ? `<g opacity="${Math.min(1, s * 1.5)}">
      <rect x="${PX + PW / 2 - 6 * u - measureText(titleText, { family: "Montserrat", size: tsz, weight: 900 }).width / 2 - 20 * u}" y="${PY + PH / 2 - tsz * 0.8 + yOff}" width="${10 * u}" height="${tsz}" fill="${accent}"/>
      <text x="${PX + PW / 2}" y="${PY + PH / 2 + tsz * 0.15 + yOff}" text-anchor="middle" font-family="Montserrat" font-weight="900"
        font-size="${tsz}" fill="${CREAM}">${escapeXml(titleText)}</text>
      <rect x="${PX + PW / 2 - 140 * u * s}" y="${PY + PH / 2 + tsz * 0.45 + yOff}" width="${280 * u * s}" height="${6 * u}" fill="${accent}"/>
    </g>` : `<text x="${PX + PW / 2}" y="${PY + PH / 2}" text-anchor="middle" font-family="'IBM Plex Mono'" font-size="${24 * u}" fill="#3F5249">compiling…</text>`}
  </g>`;

  // inspector card
  const ins = spring({ frame: frame - 190, fps, damping: 16 });
  const IY = 760 * u;
  const field = (i, label, valueSvg) => `<text x="${PX + 30 * u}" y="${IY + 62 * u + i * 56 * u}" font-family="'Source Sans 3'" font-weight="600" font-size="${26 * u}" fill="${MUTED}">${label}</text>${valueSvg(IY + 62 * u + i * 56 * u)}`;
  const sliderPos = interpolate(size, [12, 200], [0, 1]);
  const inspector = `<g opacity="${Math.min(1, ins)}" transform="translate(0 ${(1 - ins) * 40 * u})">
    <rect x="${PX}" y="${IY}" width="${PW}" height="${200 * u}" rx="${12 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
    <text x="${PX + PW - 24 * u}" y="${IY + 32 * u}" text-anchor="end" font-family="'IBM Plex Mono'" font-size="${18 * u}" fill="${MUTED}">INSPECTOR</text>
    ${field(0, "Title", (y) => `<rect x="${PX + 180 * u}" y="${y - 30 * u}" width="${300 * u}" height="${42 * u}" rx="${6 * u}" fill="#0A0F0D"/><text x="${PX + 194 * u}" y="${y}" font-family="'Source Sans 3'" font-size="${26 * u}" fill="${CREAM}">${escapeXml(titleText)}</text>`)}
    ${field(1, "Accent", (y) => `<rect x="${PX + 180 * u}" y="${y - 30 * u}" width="${80 * u}" height="${42 * u}" rx="${6 * u}" fill="${accent}"/>`)}
    ${field(2, "Size", (y) => `<rect x="${PX + 180 * u}" y="${y - 12 * u}" width="${400 * u}" height="${6 * u}" rx="${3 * u}" fill="#2F4038"/><circle cx="${PX + 180 * u + 400 * u * sliderPos}" cy="${y - 9 * u}" r="${14 * u}" fill="${CREAM}"/><text x="${PX + 610 * u}" y="${y}" font-family="'IBM Plex Mono'" font-size="${24 * u}" fill="${CREAM}">${Math.round(size)}</text>`)}
  </g>`;

  return svg(ctx, `
    <text x="${120 * u}" y="${130 * u}" opacity="${head}" font-family="'IBM Plex Mono'" font-weight="500" font-size="${30 * u}"
      letter-spacing="${6 * u}" fill="${CORAL}">${escapeXml(props.kicker)}</text>
    <text x="${120 * u}" y="${225 * u}" opacity="${sub}" transform="translate(${(1 - sub) * -60 * u} 0)" font-family="Montserrat" font-weight="900"
      font-size="${80 * u}" fill="${CREAM}">${escapeXml(props.title)}</text>
    <g opacity="${panelIn}" transform="translate(0 ${(1 - panelIn) * 60 * u})">
      <rect x="${80 * u}" y="${300 * u}" width="${940 * u}" height="${660 * u}" rx="${12 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
      <circle cx="${110 * u}" cy="${324 * u}" r="${7 * u}" fill="${CORAL}"/><circle cx="${134 * u}" cy="${324 * u}" r="${7 * u}" fill="${YELLOW}"/><circle cx="${158 * u}" cy="${324 * u}" r="${7 * u}" fill="${GREEN}"/>
      <text x="${990 * u}" y="${330 * u}" text-anchor="end" font-family="'IBM Plex Mono'" font-size="${20 * u}" fill="${MUTED}">graphics/launch.js</text>
      <g transform="translate(0 ${40 * u})">${code}</g>
    </g>
    ${preview}${inspector}`, { background: BG });
}

export const meta = { name: "FJ Built-ins", durationInFrames: 240 };
export const schema = {
  kicker: { type: "string", default: "MOTION GRAPHICS" },
  title: { type: "string", default: "Six built-ins. Or write your own." },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", TEAL = "#2E9C8A", MUTED = "#7F938A";

function barChart(f, w, h, u, fps) {
  const vals = [0.45, 0.7, 0.55, 0.9, 0.65];
  const cols = [GREEN, TEAL, YELLOW, CORAL, GREEN];
  const bw = w / 9;
  return vals.map((v, i) => {
    const s = spring({ frame: f - i * 5, fps, damping: 12 });
    const bh = v * h * 0.75 * s;
    return `<rect x="${w * 0.08 + i * bw * 1.7}" y="${h * 0.88 - bh}" width="${bw}" height="${bh}" rx="${3 * u}" fill="${cols[i]}"/>`;
  }).join("") + `<line x1="${w * 0.05}" y1="${h * 0.88}" x2="${w * 0.95}" y2="${h * 0.88}" stroke="${MUTED}" stroke-width="${2 * u}"/>`;
}
function callout(f, w, h, u, fps) {
  const cx = w * 0.32, cy = h * 0.5, r = h * 0.22;
  const ring = evolvePath(interpolate(f, [0, 25], [0, 1], { easing: Easing.inOutCubic, clamp: true }),
    `M ${cx + r} ${cy} A ${r} ${r} 0 1 1 ${cx + r - 0.01} ${cy - 0.5}`);
  const d = `M ${cx + r * 0.8} ${cy - r * 0.6} Q ${w * 0.55} ${h * 0.12} ${w * 0.68} ${h * 0.3}`;
  const a = evolvePath(interpolate(f, [20, 40], [0, 1], { clamp: true, easing: Easing.outCubic }), d);
  const t = spring({ frame: f - 38, fps, damping: 12 });
  const pulse = 1 + 0.06 * Math.sin(f / 5);
  return `<circle cx="${cx}" cy="${cy}" r="${r * 0.55}" fill="${TEAL}" opacity="0.5"/>
    <path d="M ${cx + r} ${cy} A ${r} ${r} 0 1 1 ${cx + r - 0.01} ${cy - 0.5}" fill="none" stroke="${YELLOW}" stroke-width="${6 * u}"
      stroke-dasharray="${ring.strokeDasharray}" stroke-dashoffset="${ring.strokeDashoffset}" transform="translate(${cx} ${cy}) scale(${pulse}) translate(${-cx} ${-cy})"/>
    <path d="${d}" fill="none" stroke="${YELLOW}" stroke-width="${5 * u}" stroke-linecap="round" stroke-dasharray="${a.strokeDasharray}" stroke-dashoffset="${a.strokeDashoffset}"/>
    <g opacity="${Math.min(1, t)}" transform="translate(${w * 0.7} ${h * 0.36}) scale(${t})">
      <rect x="0" y="${-30 * u}" width="${120 * u}" height="${48 * u}" rx="${8 * u}" fill="${YELLOW}"/>
      <text x="${60 * u}" y="${3 * u}" text-anchor="middle" font-family="Montserrat" font-weight="900" font-size="${26 * u}" fill="${BG}">NEW!</text></g>`;
}
function counter(f, w, h, u) {
  const v = interpolate(f, [0, 70], [0, 25000], { easing: Easing.outExpo, clamp: true });
  return `<text x="${w / 2}" y="${h * 0.56}" text-anchor="middle" font-family="'IBM Plex Mono'" font-weight="500" font-size="${74 * u}" fill="${CREAM}">${formatNumber(Math.round(v))}</text>
    <text x="${w / 2}" y="${h * 0.78}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600" font-size="${28 * u}" letter-spacing="${4 * u}" fill="${YELLOW}">VIEWS</text>`;
}
function kinetic(f, w, h, u, fps) {
  const words = ["MAKE", "IT", "MOVE"];
  let x = w * 0.1, out = "";
  words.forEach((wd, i) => {
    const s = spring({ frame: f - i * 9, fps, damping: 9, stiffness: 160 });
    const size = 70 * u;
    const ww = measureText(wd, { family: "Anton", size }).width;
    out += `<g transform="translate(${x + ww / 2} ${h * 0.62}) scale(${s}) rotate(${(1 - s) * -20})"><text x="0" y="0" text-anchor="middle" font-family="Anton" font-size="${size}" fill="${i === 2 ? CORAL : CREAM}">${wd}</text></g>`;
    x += ww + 18 * u;
  });
  return out;
}
function lowerThird(f, w, h, u, fps) {
  const x = interpolate(spring({ frame: f, fps, damping: 16 }), [0, 1], [-w, w * 0.08]);
  const t = interpolate(f, [10, 22], [0, 1], { clamp: true });
  return `<rect x="${x}" y="${h * 0.45}" width="${w * 0.78}" height="${h * 0.34}" fill="${BG}"/>
    <rect x="${x}" y="${h * 0.45}" width="${8 * u}" height="${h * 0.34}" fill="${CORAL}"/>
    <text x="${x + 26 * u}" y="${h * 0.6}" opacity="${t}" font-family="Montserrat" font-weight="800" font-size="${34 * u}" fill="${CREAM}">Alex Rivera</text>
    <text x="${x + 26 * u}" y="${h * 0.72}" opacity="${t}" font-family="'Source Sans 3'" font-weight="500" font-size="${24 * u}" fill="${MUTED}">Director of Photography</text>`;
}
function titleCard(f, w, h, u) {
  const fade = interpolate(f, [0, 15], [0, 1], { clamp: true });
  const d = `M ${w * 0.22} ${h * 0.7} q ${w * 0.28} ${h * 0.08} ${w * 0.56} 0`;
  const e = evolvePath(interpolate(f, [12, 34], [0, 1], { clamp: true, easing: Easing.inOutCubic }), d);
  return `<text x="${w / 2}" y="${h * 0.58}" opacity="${fade}" text-anchor="middle" font-family="'Source Serif 4'" font-weight="700" font-style="italic" font-size="${66 * u}" fill="${CREAM}">Chapter One</text>
    <path d="${d}" fill="none" stroke="${YELLOW}" stroke-width="${6 * u}" stroke-linecap="round" stroke-dasharray="${e.strokeDasharray}" stroke-dashoffset="${e.strokeDashoffset}"/>`;
}

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const head = spring({ frame, fps, damping: 16 });
  const sub = spring({ frame: frame - 6, fps, damping: 16 });
  const cards = [["Bar Chart", barChart], ["Callout", callout], ["Counter", counter],
    ["Kinetic Type", kinetic], ["Lower Third", lowerThird], ["Title Card", titleCard]];
  const cw = 520 * u, ch = 290 * u, gx = 40 * u, gy = 70 * u;
  const x0 = (ctx.width - (3 * cw + 2 * gx)) / 2, y0 = 310 * u;
  let grid = "";
  cards.forEach(([name, fn], i) => {
    const col = i % 3, row = Math.floor(i / 3);
    const start = 12 + i * 7;
    const s = spring({ frame: frame - start, fps, damping: 15 });
    const x = x0 + col * (cw + gx), y = y0 + row * (ch + gy);
    const f = Math.max(0, frame - start - 8);
    // each card replays its animation every 120 frames
    const lf = f % 120;
    grid += `<g opacity="${Math.min(1, s)}" transform="translate(${x} ${y + (1 - s) * 50 * u})">
      <clipPath id="c${i}"><rect width="${cw}" height="${ch}" rx="${12 * u}"/></clipPath>
      <rect width="${cw}" height="${ch}" rx="${12 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
      <g clip-path="url(#c${i})">${fn(lf, cw, ch, u, fps)}</g>
      <text x="0" y="${ch + 42 * u}" font-family="'Source Sans 3'" font-weight="700" font-size="${30 * u}" fill="${CREAM}">${name}</text>
    </g>`;
  });
  return svg(ctx, `
    <text x="${120 * u}" y="${130 * u}" opacity="${head}" font-family="'IBM Plex Mono'" font-weight="500" font-size="${30 * u}"
      letter-spacing="${6 * u}" fill="${CORAL}">${escapeXml(props.kicker)}</text>
    <text x="${120 * u}" y="${225 * u}" opacity="${sub}" transform="translate(${(1 - sub) * -60 * u} 0)" font-family="Montserrat" font-weight="900"
      font-size="${80 * u}" fill="${CREAM}">${escapeXml(props.title)}</text>
    ${grid}`, { background: BG });
}

export const meta = { name: "FJ Action dial", durationInFrames: 210 };
export const schema = {
  value: { type: "number", default: 12, min: 0, max: 100 },
  accent: { type: "color", default: "#F4653F" },
  spin: { type: "number", default: 0, min: -720, max: 720 },
  actionStart: { type: "number", default: 45, min: 0, animate: false, help: "Where the action is drawn on the lane, in clip frames" },
  actionEnd: { type: "number", default: 135, min: 0, animate: false },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", MUTED = "#7F938A";

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const head = spring({ frame, fps, damping: 16 });
  const sub = spring({ frame: frame - 6, fps, damping: 16 });
  const body = interpolate(frame, [14, 30], [0, 1], { clamp: true });
  // the dial
  const cx = 1340 * u, cy = 520 * u, r = 230 * u;
  const appear = spring({ frame: frame - 8, fps, damping: 14 });
  const v = props.value / 100;
  const a0 = -225, sweep = 270;
  const arc = (frac) => {
    const a = ((a0 + sweep * frac) * Math.PI) / 180, s = (a0 * Math.PI) / 180;
    const large = sweep * frac > 180 ? 1 : 0;
    return `M ${cx + r * Math.cos(s)} ${cy + r * Math.sin(s)} A ${r} ${r} 0 ${large} 1 ${cx + r * Math.cos(a)} ${cy + r * Math.sin(a)}`;
  };
  let ticks = "";
  for (let i = 0; i <= 20; i++) {
    const a = ((a0 + (sweep * i) / 20) * Math.PI) / 180;
    const r1 = r + 30 * u, r2 = r + (i % 5 ? 42 : 56) * u;
    ticks += `<line x1="${cx + r1 * Math.cos(a)}" y1="${cy + r1 * Math.sin(a)}" x2="${cx + r2 * Math.cos(a)}" y2="${cy + r2 * Math.sin(a)}" stroke="${i / 20 <= v ? props.accent : "#2F4038"}" stroke-width="${4 * u}"/>`;
  }
  const na = ((a0 + sweep * v) * Math.PI) / 180;
  let orbit = "";
  for (let i = 0; i < 6; i++) {
    const a = ((props.spin + i * 60) * Math.PI) / 180;
    orbit += `<circle cx="${cx + (r - 70 * u) * Math.cos(a)}" cy="${cy + (r - 70 * u) * Math.sin(a)}" r="${7 * u}" fill="${props.accent}" opacity="0.5"/>`;
  }
  const dial = `<g opacity="${Math.min(1, appear)}" transform="translate(${cx} ${cy}) scale(${appear}) translate(${-cx} ${-cy})">
    <circle cx="${cx}" cy="${cy}" r="${r + 80 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
    <path d="${arc(1)}" fill="none" stroke="#24332B" stroke-width="${26 * u}" stroke-linecap="round"/>
    ${v > 0.002 ? `<path d="${arc(v)}" fill="none" stroke="${props.accent}" stroke-width="${26 * u}" stroke-linecap="round"/>` : ""}
    ${ticks}${orbit}
    <circle cx="${cx + r * Math.cos(na)}" cy="${cy + r * Math.sin(na)}" r="${20 * u}" fill="${CREAM}"/>
    <text x="${cx}" y="${cy + 40 * u}" text-anchor="middle" font-family="'IBM Plex Mono'" font-weight="500" font-size="${120 * u}" fill="${CREAM}">${Math.round(props.value)}</text>
    <text x="${cx}" y="${cy + 100 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="700" font-size="${28 * u}" letter-spacing="${5 * u}" fill="${props.accent}">props.value</text>
  </g>`;
  // the action lane, as the timeline draws it
  const LX = 120 * u, LW = 760 * u, LY = 840 * u, dur = ctx.durationInFrames;
  const fx = (f) => LX + (f / dur) * LW;
  const ph = fx(frame);
  const lane = `<g opacity="${body}">
    <rect x="${LX}" y="${LY}" width="${LW}" height="${70 * u}" rx="${4 * u}" fill="${GREEN}" opacity="0.35"/>
    <text x="${LX + 12 * u}" y="${LY + 44 * u}" font-family="'Source Sans 3'" font-weight="700" font-size="${24 * u}" fill="${CREAM}">Graphic clip</text>
    <rect x="${fx(props.actionStart)}" y="${LY - 40 * u}" width="${fx(props.actionEnd) - fx(props.actionStart)}" height="${30 * u}" rx="${15 * u}" fill="${YELLOW}"/>
    <text x="${(fx(props.actionStart) + fx(props.actionEnd)) / 2}" y="${LY - 18 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="700" font-size="${20 * u}" fill="${BG}">Action · ease in-out</text>
    <line x1="${ph}" y1="${LY - 60 * u}" x2="${ph}" y2="${LY + 90 * u}" stroke="${CORAL}" stroke-width="${4 * u}"/>
    <path d="M ${ph - 12 * u} ${LY - 66 * u} H ${ph + 12 * u} L ${ph} ${LY - 46 * u} Z" fill="${CORAL}"/>
  </g>`;
  const lines = wrapText("Any property of any clip — position, scale, opacity, colour, or a graphic's own props — eases to a new value across an action on the timeline.", 760 * u, { family: "Source Sans 3", size: 40 * u, weight: 500 });
  return svg(ctx, `
    <text x="${120 * u}" y="${130 * u}" opacity="${head}" font-family="'IBM Plex Mono'" font-weight="500" font-size="${30 * u}"
      letter-spacing="${6 * u}" fill="${CORAL}">ACTIONS</text>
    <text x="${120 * u}" y="${225 * u}" opacity="${sub}" transform="translate(${(1 - sub) * -60 * u} 0)" font-family="Montserrat" font-weight="900"
      font-size="${80 * u}" fill="${CREAM}">Animate from the timeline</text>
    <g opacity="${body}">${textLines(lines, { x: 120 * u, y: 380 * u, anchor: "start", fill: "#C9D4CE", font: { family: "Source Sans 3", size: 40 * u, weight: 500 }, lineHeight: 56 * u })}</g>
    ${dial}${lane}`, { background: BG });
}

