export const meta = { name: "FJ Colour field", durationInFrames: 180 };
export const schema = {
  speed: { type: "number", default: 1, min: 0, max: 5 },
};

const COLS = ["#F4653F", "#F2C14E", "#1F8564", "#2E9C8A", "#E8456B", "#F28C38"];

export function render(frame, props, ctx) {
  const t = (frame / ctx.fps) * props.speed;
  const w = ctx.width, h = ctx.height;
  let blobs = "";
  for (let i = 0; i < 9; i++) {
    const x = w * (0.5 + 0.55 * noise2D(`x${i}`, t * 0.25, i));
    const y = h * (0.5 + 0.55 * noise2D(`y${i}`, t * 0.25, i));
    const r = h * (0.35 + 0.15 * noise2D(`r${i}`, t * 0.3, 0));
    blobs += `<circle cx="${x}" cy="${y}" r="${r}" fill="url(#b${i % COLS.length})"/>`;
  }
  let defs = COLS.map((c, i) => `<radialGradient id="b${i}"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></radialGradient>`).join("");
  let stripes = "";
  const off = (t * 120) % 80;
  for (let x = -h; x < w + h; x += 80) {
    stripes += `<line x1="${x + off}" y1="0" x2="${x + off - h}" y2="${h}" stroke="#FBF8F1" stroke-opacity="0.07" stroke-width="18"/>`;
  }
  return svg(ctx, `<defs>${defs}</defs><rect width="${w}" height="${h}" fill="#7A2E3A"/>${blobs}${stripes}`);
}

export const meta = { name: "FJ Matte letters", durationInFrames: 180 };
export const schema = {
  word: { type: "string", default: "MOTION" },
};

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps, dur = ctx.durationInFrames;
  const size = 380 * u;
  const letters = [...props.word];
  const widths = letters.map((c) => measureText(c, { family: "Anton", size }).width);
  const gap = 14 * u;
  const total = widths.reduce((a, b) => a + b, 0) + gap * (letters.length - 1);
  let x = (ctx.width - total) / 2, out = "";
  const exit = interpolate(frame, [dur - 18, dur - 2], [1, 0], { easing: Easing.inCubic, clamp: true });
  letters.forEach((c, i) => {
    const s = spring({ frame: frame - 10 - i * 4, fps, damping: 10, stiffness: 140 }) * exit;
    const cx = x + widths[i] / 2, cy = 640 * u;
    const bob = Math.sin((frame + i * 9) / 12) * 10 * u;
    out += `<g transform="translate(${cx} ${cy + bob}) scale(${Math.max(0, s)}) translate(${-cx} ${-cy})">
      <text x="${cx}" y="${cy + size * 0.36}" text-anchor="middle" font-family="Anton" font-size="${size}" fill="#ffffff">${escapeXml(c)}</text></g>`;
    x += widths[i] + gap;
  });
  return svg(ctx, out);
}

export const meta = { name: "FJ Grading", durationInFrames: 210 };
export const schema = {
  kicker: { type: "string", default: "COLOUR" },
  title: { type: "string", default: "Grade it like a colourist" },
  chips: { type: "string", default: "Wheels,Curves,Looks & .cube LUTs,Qualifiers,Scopes,HDR & camera log", animate: false },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", MUTED = "#7F938A";

function scene(w, h, graded, t) {
  // a little landscape drawn in two grades: flat (log-like) and finished
  const sky = graded ? ["#1B3B6F", "#F28C38"] : ["#5E6A73", "#9C928A"];
  const sun = graded ? "#FFD27A" : "#C9C2B5";
  const hill1 = graded ? "#1F6B4F" : "#5D6B63";
  const hill2 = graded ? "#0F3B2E" : "#4A5550";
  const water = graded ? "#2B5C8A" : "#6C7479";
  const sy = h * (0.52 - 0.04 * Math.sin(t / 40));
  return `<defs><linearGradient id="sky${graded}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${sky[0]}"/><stop offset="1" stop-color="${sky[1]}"/></linearGradient></defs>
    <rect width="${w}" height="${h}" fill="url(#sky${graded})"/>
    <circle cx="${w * 0.62}" cy="${sy}" r="${h * 0.12}" fill="${sun}"/>
    <path d="M 0 ${h * 0.62} C ${w * 0.2} ${h * 0.45} ${w * 0.35} ${h * 0.5} ${w * 0.55} ${h * 0.6} S ${w * 0.85} ${h * 0.5} ${w} ${h * 0.58} V ${h} H 0 Z" fill="${hill1}"/>
    <path d="M 0 ${h * 0.75} C ${w * 0.3} ${h * 0.62} ${w * 0.6} ${h * 0.8} ${w} ${h * 0.68} V ${h} H 0 Z" fill="${hill2}"/>
    <rect y="${h * 0.86}" width="${w}" height="${h * 0.14}" fill="${water}"/>`;
}

function wheel(cx, cy, r, label, dx, dy, u) {
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="url(#hue)" opacity="0.85"/>
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="url(#fade)"/>
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${LINE}" stroke-width="${3 * u}"/>
    <circle cx="${cx + dx * r}" cy="${cy + dy * r}" r="${9 * u}" fill="${CREAM}" stroke="${BG}" stroke-width="${3 * u}"/>
    <text x="${cx}" y="${cy + r + 40 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="700" font-size="${26 * u}" fill="${MUTED}">${label}</text>`;
}

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const head = spring({ frame, fps, damping: 16 });
  const sub = spring({ frame: frame - 6, fps, damping: 16 });
  const pin = spring({ frame: frame - 10, fps, damping: 18 });
  const PX = 120 * u, PY = 300 * u, PW = 1040 * u, PH = 585 * u;
  const split = interpolate(frame, [30, 90, 140, 190], [0.05, 0.95, 0.5, 0.5], { easing: Easing.inOutCubic, clamp: true });
  const sx = PX + PW * split;
  const viewer = `<g opacity="${pin}" transform="translate(0 ${(1 - pin) * 60 * u})">
    <clipPath id="vp"><rect x="${PX}" y="${PY}" width="${PW}" height="${PH}" rx="${12 * u}"/></clipPath>
    <clipPath id="left"><rect x="${PX}" y="${PY}" width="${sx - PX}" height="${PH}"/></clipPath>
    <g clip-path="url(#vp)">
      <g transform="translate(${PX} ${PY})">${scene(PW, PH, true, frame)}</g>
      <g clip-path="url(#left)"><g transform="translate(${PX} ${PY})">${scene(PW, PH, false, frame)}</g></g>
    </g>
    <line x1="${sx}" y1="${PY}" x2="${sx}" y2="${PY + PH}" stroke="${CREAM}" stroke-width="${4 * u}"/>
    <text x="${PX + 24 * u}" y="${PY + 48 * u}" font-family="'IBM Plex Mono'" font-size="${24 * u}" fill="${CREAM}">UNGRADED</text>
    <text x="${PX + PW - 24 * u}" y="${PY + 48 * u}" text-anchor="end" font-family="'IBM Plex Mono'" font-size="${24 * u}" fill="${CREAM}">GRADED</text>
  </g>`;
  // wheels and a waveform on the right
  const wIn = spring({ frame: frame - 24, fps, damping: 16 });
  const WX = 1260 * u, wr = 82 * u;
  const m = interpolate(frame, [40, 150], [0, 1], { easing: Easing.inOutSine, clamp: true });
  const wheels = `<g opacity="${Math.min(1, wIn)}">
    ${wheel(WX + 90 * u, 400 * u, wr, "Lift", -0.35 * m, 0.25 * m, u)}
    ${wheel(WX + 320 * u, 400 * u, wr, "Gamma", 0.1 * m, -0.1 * m, u)}
    ${wheel(WX + 550 * u, 400 * u, wr, "Gain", 0.4 * m, -0.3 * m, u)}
  </g>`;
  let wf = "";
  const SX = WX, SY = 600 * u, SW = 640 * u, SH = 285 * u;
  for (let i = 0; i < 64; i++) {
    for (let k = 0; k < 6; k++) {
      const base = 0.35 + 0.25 * Math.sin(i / 7 + k) * (0.4 + 0.6 * m) + 0.12 * noise2D(k, i / 5, frame / 30);
      const y = SY + SH * (1 - Math.max(0.03, Math.min(0.97, base + (k - 2.5) * 0.06 * (0.6 + m))));
      wf += `<rect x="${SX + 10 * u + i * (SW - 20 * u) / 64}" y="${y}" width="${4 * u}" height="${3 * u}" fill="#7FD1B9" opacity="0.7"/>`;
    }
  }
  const scope = `<g opacity="${Math.min(1, wIn)}"><rect x="${SX}" y="${SY}" width="${SW}" height="${SH}" rx="${10 * u}" fill="#0A0F0D" stroke="${LINE}" stroke-width="${2 * u}"/>${wf}
    <text x="${SX + SW - 16 * u}" y="${SY + 32 * u}" text-anchor="end" font-family="'IBM Plex Mono'" font-size="${18 * u}" fill="${MUTED}">WAVEFORM</text></g>`;
  let x = 120 * u, chips = "";
  props.chips.split(",").forEach((c, i) => {
    const s = spring({ frame: frame - 60 - i * 5, fps, damping: 14 });
    const w = measureText(c, { family: "Source Sans 3", size: 28 * u, weight: 600 }).width + 36 * u;
    chips += `<g opacity="${Math.min(1, s)}"><rect x="${x}" y="${930 * u}" width="${w}" height="${50 * u}" rx="${25 * u}" fill="none" stroke="${GREEN}" stroke-width="${2 * u}"/>
      <text x="${x + w / 2}" y="${964 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600" font-size="${28 * u}" fill="${CREAM}">${escapeXml(c)}</text></g>`;
    x += w + 14 * u;
  });
  return svg(ctx, `<defs>
      <radialGradient id="fade"><stop offset="0" stop-color="#888" stop-opacity="1"/><stop offset="1" stop-color="#888" stop-opacity="0"/></radialGradient>
