export const meta = { name: "FJ Clean-up and audio", durationInFrames: 210 };
export const schema = {
  kicker: { type: "string", default: "AUDIO & CLEAN-UP" },
  title: { type: "string", default: "Cut the dead air in one step" },
  chips: { type: "string", default: "Remove Silences,Remove Filler Words,Synchronize Audio,Speed ramps,Ducking & noise reduction", animate: false },
};

const BG = "#0D1512", PANEL = "#151F1A", LINE = "#24332B", CREAM = "#FBF8F1", GREEN = "#1F8564",
  YELLOW = "#F2C14E", CORAL = "#F4653F", TEAL = "#2E9C8A", MUTED = "#7F938A";

// speech segments [start, end] on a 0..30 scale; gaps are silences, "um" marks fillers
const SEGS = [[0, 4.2], [6.0, 10.5], [11.3, 12.1, "um"], [12.4, 17.0], [19.5, 23.0], [23.5, 24.2, "uh"], [24.4, 30]];

export function render(frame, props, ctx) {
  const u = ctx.height / 1080, fps = ctx.fps;
  const head = spring({ frame, fps, damping: 16 });
  const sub = spring({ frame: frame - 6, fps, damping: 16 });
  const pin = spring({ frame: frame - 10, fps, damping: 18 });
  const L = 120 * u, R = ctx.width - 120 * u, Y = 560 * u, H = 200 * u;
  const mark = interpolate(frame, [40, 70], [0, 1], { clamp: true });
  const cut = interpolate(frame, [95, 135], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  // positions: before the cut the full 30 s span, after it the gaps close
  const kept = SEGS.filter((s) => !s[2]);
  const keptLen = kept.reduce((n, s) => n + s[1] - s[0], 0);
  const scaleBefore = (R - L) / 30, scaleAfter = (R - L) / 30; // same scale: the cut shortens the clip
  let acc = 0;
  const after = new Map();
  kept.forEach((s) => { after.set(s, acc); acc += s[1] - s[0]; });
  let body = "";
  SEGS.forEach((s, i) => {
    const filler = !!s[2];
    const x0 = L + s[0] * scaleBefore;
    const x1 = filler ? x0 : L + after.get(s) * scaleAfter;
    const x = x0 + (x1 - x0) * cut;
    const w = (s[1] - s[0]) * scaleBefore;
    const op = filler ? 1 - cut : 1;
    let bars = "";
    for (let k = 0; k < w / (7 * u); k++) {
      const amp = (0.25 + 0.75 * Math.abs(noise2D(`s${i}`, k / 6, 0))) * H * 0.42;
      bars += `<rect x="${x + k * 7 * u}" y="${Y + H / 2 - amp}" width="${4 * u}" height="${amp * 2}" fill="${filler ? YELLOW : TEAL}"/>`;
    }
    body += `<g opacity="${op}">${bars}${filler ? `<text x="${x + w / 2}" y="${Y - 24 * u}" text-anchor="middle" font-family="Montserrat" font-weight="900" font-size="${34 * u}" fill="${YELLOW}" opacity="${mark}">${s[2]}</text>` : ""}</g>`;
  });
  // silence shading between segments, before the cut
  let gaps = "";
  for (let i = 0; i < SEGS.length - 1; i++) {
    const a = SEGS[i][1], b = SEGS[i + 1][0];
    if (b - a > 0.15) {
      gaps += `<rect x="${L + a * scaleBefore}" y="${Y}" width="${(b - a) * scaleBefore}" height="${H}" fill="${CORAL}" opacity="${0.28 * mark * (1 - cut)}"/>`;
    }
  }
  const saved = Math.round((30 - keptLen) * 10) / 10;
  const badge = interpolate(frame, [135, 150], [0, 1], { clamp: true });
  let x = 120 * u, chips = "";
  props.chips.split(",").forEach((c, i) => {
    const s = spring({ frame: frame - 140 - i * 5, fps, damping: 14 });
    const w = measureText(c, { family: "Source Sans 3", size: 28 * u, weight: 600 }).width + 36 * u;
    chips += `<g opacity="${Math.min(1, s)}"><rect x="${x}" y="${900 * u}" width="${w}" height="${50 * u}" rx="${25 * u}" fill="none" stroke="${GREEN}" stroke-width="${2 * u}"/>
      <text x="${x + w / 2}" y="${934 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600" font-size="${28 * u}" fill="${CREAM}">${escapeXml(c)}</text></g>`;
    x += w + 14 * u;
  });
  return svg(ctx, `
    <text x="${120 * u}" y="${130 * u}" opacity="${head}" font-family="'IBM Plex Mono'" font-weight="500" font-size="${30 * u}"
      letter-spacing="${6 * u}" fill="${CORAL}">${escapeXml(props.kicker)}</text>
    <text x="${120 * u}" y="${225 * u}" opacity="${sub}" transform="translate(${(1 - sub) * -60 * u} 0)" font-family="Montserrat" font-weight="900"
      font-size="${80 * u}" fill="${CREAM}">${escapeXml(props.title)}</text>
    <g opacity="${pin}">
      <rect x="${L - 30 * u}" y="${Y - 110 * u}" width="${R - L + 60 * u}" height="${H + 180 * u}" rx="${14 * u}" fill="${PANEL}" stroke="${LINE}" stroke-width="${2 * u}"/>
      ${gaps}${body}
      <g opacity="${badge}"><rect x="${R - 330 * u}" y="${Y + H + 10 * u}" width="${330 * u}" height="${50 * u}" rx="${25 * u}" fill="${YELLOW}"/>
      <text x="${R - 165 * u}" y="${Y + H + 44 * u}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="700" font-size="${28 * u}" fill="${BG}">${saved} s removed · 1 undo</text></g>
    </g>
    ${chips}`, { background: BG });
}

