      <rect x="${SX + 560 * u}" y="${SY + 300 * u}" width="${150 * u}" height="${54 * u}" rx="${10 * u}" fill="${TEAL}"/>
      ${clicks}
      <path d="M ${curX} ${curY} l 0 ${34 * u} l ${9 * u} ${-8 * u} l ${8 * u} ${17 * u} l ${7 * u} ${-3 * u} l ${-8 * u} ${-17 * u} l ${12 * u} 0 Z" fill="#111" stroke="#fff" stroke-width="${2 * u}"/>
      <g opacity="${Math.min(1, cam)}">
