        <g clip-path="url(#cam)"><rect x="${camX - 130 * u}" y="${camY - 130 * u}" width="${260 * u}" height="${260 * u}" fill="#3A4B43"/>
          <circle cx="${camX}" cy="${camY - 20 * u}" r="${46 * u}" fill="#C9A88B"/>
