  const typed = Math.floor(interpolate(frame, [20, 60], [0, props.prompt.length], { clamp: true }));
  let lines = `<text x="${TX + 36 * u}" y="${TY + 90 * u}" font-family="'IBM Plex Mono'" font-size="${fs * 1.1}" fill="${CREAM}"><tspan fill="${CORAL}">&gt; </tspan>${escapeXml(props.prompt.slice(0, typed))}${frame < 64 && Math.floor(frame / 8) % 2 ? "▌" : ""}</text>`;
  CALLS.forEach(([tool, args, res], i) => {
